begin;
create schema mentalist;
revoke all on schema mentalist from public, anon, authenticated;
set local search_path=mentalist,public,extensions;
create table releases(version int primary key, digest text not null, published_at timestamptz default now());
create table skills(version int references releases, id text, definition jsonb not null, primary key(version,id));
create table levels(version int references releases, id text, skill text not null, definition jsonb not null, primary key(version,id),foreign key(version,skill) references skills);
create table published_levels(version int,level text,reviewed_by text not null,published_at timestamptz not null default now(),primary key(version,level),foreign key(version,level) references levels);
create table evidence(version int references releases,group_id text,requirement text,levels jsonb not null,primary key(version,group_id,requirement));
create table templates(version int references releases,id text,definition jsonb not null,primary key(version,id));
create table questions(version int references releases,id text,definition jsonb not null,primary key(version,id));
create table sets(version int references releases,id text,level text not null,positions jsonb not null check(jsonb_array_length(positions)=12),primary key(version,id),foreign key(version,level) references levels);
create table credentials(profile uuid primary key references public.profiles on delete cascade,pin_hash text not null);
create table login_limits(name text primary key, since timestamptz not null, attempts integer not null);
create table sessions(token text primary key,profile uuid not null references public.profiles on delete cascade,started timestamptz not null default now(),expires timestamptz not null,ended timestamptz);
create table classes(id uuid primary key default gen_random_uuid(), teacher uuid not null references public.teachers,name text not null,timezone text not null default 'America/Chicago');
create table roster(class uuid references classes,profile uuid references public.profiles,multiplier numeric not null default 1 check(multiplier between 0.5 and 4),primary key(class,profile));
create table decisions(id uuid primary key default gen_random_uuid(), class uuid, profile uuid, skill text not null, teacher uuid not null references public.teachers,kind text not null check(kind in ('assignment','placement')), created timestamptz default now(),due date,removed timestamptz, foreign key(class,profile) references roster);
create unique index active_decisions on decisions(class,profile,skill,kind) where removed is null;
create table runs(id uuid primary key default gen_random_uuid(),profile uuid not null references public.profiles,session_token text references sessions,class uuid references classes,version int not null,level text not null,skill text not null,set_id text not null,started timestamptz not null default clock_timestamp(),ended timestamptz,status text not null default 'active' check(status in ('active','interrupted','knockdown','completed')),hp int not null default 100,enemy_hp int not null default 40,defeats int not null default 0,policy jsonb not null,result jsonb,bonus boolean not null default false,foreign key(version,set_id) references sets);
create unique index one_active_run on runs(profile) where status='active';
create index run_history on runs(profile,level,started desc);
create table encounters(id uuid primary key default gen_random_uuid(),run uuid references runs,position int not null check(position between 1 and 12),question text not null,version int not null,snapshot jsonb not null,opened timestamptz not null default clock_timestamp(),resolved timestamptz,unique(run,position),foreign key(version,question) references questions);
create table events(id uuid primary key,encounter uuid not null references encounters,ordinal int not null,scored_number int,raw text not null,normalized text not null,outcome text not null check(outcome in ('correct','incorrect','simplification')),active_ms int,created timestamptz not null default clock_timestamp(),unique(encounter,ordinal),unique(encounter,scored_number));
create table clears(profile uuid references public.profiles,level text,first_run uuid not null references runs,best_run uuid not null references runs,stars int not null check(stars between 1 and 3),review_count int not null default 0,review_due timestamptz not null,primary key(profile,level));
create table cards(profile uuid references public.profiles,skill text,amount int not null default 0 check(amount>=0),upgrade int not null default 1 check(upgrade between 1 and 4),primary key(profile,skill));
create table ledger(id bigint generated always as identity primary key,profile uuid references public.profiles,source text not null,skill text,coins int not null,xp int not null,cards int not null,created timestamptz not null default now(),unique(profile,source));
create table chests(id uuid primary key default gen_random_uuid(),profile uuid references public.profiles,slot int check(slot between 0 and 3),skill text not null,reward text not null check(reward in ('coins','cards')),ready timestamptz,opened timestamptz);
create unique index occupied_slots on chests(profile,slot) where opened is null;
create table offers(profile uuid references public.profiles,checkpoint text,target text not null,expires_level text not null,run uuid references runs,expired boolean not null default false,paid boolean not null default false,primary key(profile,checkpoint));
create table recommendations(profile uuid primary key references public.profiles,level text,reason text,updated timestamptz default now());
create table receipts(profile uuid references public.profiles,id uuid,action text not null,payload_hash text not null,response jsonb not null,primary key(profile,id));
create table appearance(profile uuid primary key references public.profiles,title text,frame text);
commit;
